#include <bits/stdc++.h>
using namespace std;
#define int long long
const int MOD1=998244353;
const int MOD2=1000000007;
int totalResult;
int totalN;
int count1;
vector<int> valSet[7];
int sumSet[7];
void generateValues(int level,int prefixSum){
	if(level==7) return;
	valSet[level].push_back((count1 - prefixSum + MOD1) % MOD1);
	sumSet[level] += (count1 - prefixSum + MOD1) % MOD1;
	count1++;
	for(int digit=0; digit<=9; ++digit){
		generateValues(level+1, prefixSum*10+digit);
	}
}
bool checkRange(int x){
	const int half=1000000;
	return x*half+999999 <= totalN && x*half*10 > totalN;
}
int count2;
int powTenArr[7]={1,10,100,1000,10000,100000,1000000};
void traverseAll(int level,int number){
	if(number > totalN) return;
	if(checkRange(number)){
		for(int i=0; i<=6; ++i){
			int offset = ((count2+1 - (number*powTenArr[i])) % MOD1 + MOD1) % MOD1;
			int pos = lower_bound(valSet[i].begin(), valSet[i].end(), MOD1 - offset) - valSet[i].begin();
			totalResult += (sumSet[i] + offset * (int)valSet[i].size() - MOD1 * ((int)valSet[i].size() - pos)) % MOD2;
			totalResult %= MOD2;
		}
		count2 += count1;
	}
	else{
		count2++;
		totalResult += ((count2 - number) % MOD1 + MOD1) % MOD1;
		totalResult %= MOD2;
		for(int digit=0; digit<=9; ++digit){
			if(level==0 && digit==0) continue;
			traverseAll(level+1, number*10+digit);
		}
	}
}
int main(){
	cin >> totalN;
	generateValues(0,0);
	for(int i=0; i<=6; ++i) sort(valSet[i].begin(), valSet[i].end());
	count2 = -1;
	traverseAll(0,0);
	cout << totalResult << "\n";
}
